import { scrypt, randomBytes, timingSafeEqual, createHash } from 'node:crypto';
import { promisify } from 'node:util';

const scryptAsync = promisify(scrypt);
// Parámetros mínimos de OWASP para scrypt: N = 2^17, r = 8, p = 1.
const N = 2 ** 17, R = 8, P = 1;
const MAXMEM = 256 * 1024 * 1024; // scrypt necesita 128 * N * r bytes = 128 MiB

export async function hashear(password) {
  const sal = randomBytes(16);
  const h = await scryptAsync(password, sal, 64, { N, r: R, p: P, maxmem: MAXMEM });
  return ['scrypt', N, R, P, sal.toString('base64'), h.toString('base64')].join('$');
}

export async function verificar(password, guardado) {
  const [alg, n, r, p, sal, esperado] = guardado.split('$');
  if (alg !== 'scrypt') return false;
  const h = await scryptAsync(password, Buffer.from(sal, 'base64'), 64,
    { N: Number(n), r: Number(r), p: Number(p), maxmem: MAXMEM });
  return timingSafeEqual(h, Buffer.from(esperado, 'base64'));
}

// Un hash falso para gastar el mismo tiempo cuando el email no existe.
export const HASH_FALSO = await hashear('no-importa-esto-es-un-relleno');

export const nuevoToken = () => randomBytes(32).toString('base64url');
// El token tiene 256 bits al azar: alcanza con SHA-256, no hace falta un hash lento.
export const huella = (token) => createHash('sha256').update(token).digest('hex');

import express from 'express';
import { randomUUID } from 'node:crypto';
import { z } from 'zod';
import { pool } from './db.js';
import { hashear, verificar, HASH_FALSO, nuevoToken, huella } from './seguridad.js';

const HORAS_SESION = 8;

export function log(nivel, datos) {
  console.log(JSON.stringify({ t: new Date().toISOString(), nivel, ...datos }));
}

class ErrorHttp extends Error {
  constructor(estado, codigo, mensaje, detalles) {
    super(mensaje);
    Object.assign(this, { estado, codigo, detalles });
  }
}

// --- Esquemas de entrada: lo que no cumple, ni entra a la lógica ---
const Registro = z.object({
  email: z.email().max(120).transform((s) => s.toLowerCase()),
  nombre: z.string().trim().min(1).max(60),
  password: z.string().min(10).max(128),
});
const Login = z.object({ email: z.email().transform((s) => s.toLowerCase()), password: z.string().min(1).max(128) });
const NuevoEnvio = z.object({
  destinatario: z.string().trim().min(1).max(80),
  direccion: z.string().trim().min(1).max(120),
  bultos: z.number().int().min(1).max(500),
});
const CambioEstado = z.object({ estado: z.enum(['en_ruta', 'entregado', 'cancelado']) });
const Id = z.string().regex(/^[1-9]\d{0,17}$/);

// Regla de negocio: de qué estado se puede pasar a cuál.
const TRANSICIONES = { pendiente: ['en_ruta', 'cancelado'], en_ruta: ['entregado'], entregado: [], cancelado: [] };

const leer = (esquema, datos) => {
  const r = esquema.safeParse(datos);
  if (!r.success) {
    const detalles = r.error.issues.map((i) => ({ campo: i.path.join('.'), problema: i.message }));
    throw new ErrorHttp(400, 'entrada_invalida', 'Los datos enviados no son válidos', detalles);
  }
  return r.data;
};

// --- Middleware de autenticación: del token a la persona ---
async function exigirSesion(req, _res, next) {
  const m = /^Bearer ([A-Za-z0-9_-]{43})$/.exec(req.get('authorization') ?? '');
  if (!m) throw new ErrorHttp(401, 'sin_sesion', 'Falta una sesión válida');
  const { rows } = await pool.query(
    `select u.id, u.email from sesiones s join usuarios u on u.id = s.usuario_id
     where s.token_hash = $1 and s.expira > now()`, [huella(m[1])]);
  if (rows.length === 0) throw new ErrorHttp(401, 'sin_sesion', 'Falta una sesión válida');
  req.usuario = rows[0];
  req.tokenHash = huella(m[1]);
  next();
}

export function crearApp() {
  const app = express();
  app.disable('x-powered-by');

  app.use((req, res, next) => { // identificador de pedido + una línea de log por respuesta
    req.id = randomUUID();
    res.set('X-Request-Id', req.id);
    const t0 = process.hrtime.bigint();
    res.on('finish', () => log('info', {
      id: req.id, metodo: req.method, ruta: req.route?.path ?? 'sin_ruta',
      estado: res.statusCode, ms: Number(process.hrtime.bigint() - t0) / 1e6,
      usuario: req.usuario?.id ?? null,
    }));
    next();
  });
  app.use(express.json({ limit: '10kb' }));

  app.post('/registro', async (req, res) => {
    const d = leer(Registro, req.body);
    try {
      const { rows } = await pool.query(
        'insert into usuarios (email, nombre, password_hash) values ($1, $2, $3) returning id, email, nombre',
        [d.email, d.nombre, await hashear(d.password)]);
      res.status(201).json(rows[0]);
    } catch (e) {
      if (e.code === '23505') throw new ErrorHttp(409, 'email_repetido', 'Ya existe una cuenta con ese email');
      throw e;
    }
  });

  app.post('/login', async (req, res) => {
    const d = leer(Login, req.body);
    const { rows } = await pool.query('select id, password_hash from usuarios where email = $1', [d.email]);
    const ok = await verificar(d.password, rows[0]?.password_hash ?? HASH_FALSO);
    if (rows.length === 0 || !ok) throw new ErrorHttp(401, 'credenciales', 'Email o contraseña incorrectos');
    const token = nuevoToken();
    const { rows: [s] } = await pool.query(
      `insert into sesiones (token_hash, usuario_id, expira)
       values ($1, $2, now() + make_interval(hours => $3)) returning expira`,
      [huella(token), rows[0].id, HORAS_SESION]);
    res.json({ token, expira: s.expira });
  });

  app.post('/logout', exigirSesion, async (req, res) => {
    await pool.query('delete from sesiones where token_hash = $1', [req.tokenHash]);
    res.status(204).end();
  });

  app.get('/yo', exigirSesion, (req, res) => res.json(req.usuario));

  app.post('/envios', exigirSesion, async (req, res) => {
    const d = leer(NuevoEnvio, req.body);
    const { rows } = await pool.query(
      `insert into envios (usuario_id, destinatario, direccion, bultos) values ($1, $2, $3, $4)
       returning id, destinatario, direccion, bultos, estado, creado`,
      [req.usuario.id, d.destinatario, d.direccion, d.bultos]);
    res.status(201).json(rows[0]);
  });

  app.get('/envios', exigirSesion, async (req, res) => {
    const { rows } = await pool.query(
      `select id, destinatario, direccion, bultos, estado, creado from envios
       where usuario_id = $1 order by id desc limit 50`, [req.usuario.id]);
    res.json(rows);
  });

  // Dueño del recurso: la búsqueda lleva el usuario. Si no es tuyo, para vos no existe (404).
  async function envioPropio(req) {
    const id = leer(Id, req.params.id);
    const { rows } = await pool.query(
      'select id, destinatario, direccion, bultos, estado, creado from envios where id = $1 and usuario_id = $2',
      [id, req.usuario.id]);
    if (rows.length === 0) throw new ErrorHttp(404, 'no_encontrado', 'No existe ese envío');
    return rows[0];
  }

  app.get('/envios/:id', exigirSesion, async (req, res) => res.json(await envioPropio(req)));

  app.patch('/envios/:id/estado', exigirSesion, async (req, res) => {
    const { estado: nuevo } = leer(CambioEstado, req.body);
    const envio = await envioPropio(req);
    if (!TRANSICIONES[envio.estado].includes(nuevo)) {
      throw new ErrorHttp(409, 'transicion_invalida', `Un envío ${envio.estado} no puede pasar a ${nuevo}`);
    }
    const { rows } = await pool.query( // compare-and-set: solo si sigue en el estado que leímos
      `update envios set estado = $1 where id = $2 and usuario_id = $3 and estado = $4
       returning id, destinatario, direccion, bultos, estado, creado`,
      [nuevo, envio.id, req.usuario.id, envio.estado]);
    if (rows.length === 0) throw new ErrorHttp(409, 'cambio_concurrente', 'El envío cambió mientras lo procesábamos');
    res.json(rows[0]);
  });

  app.use((_req, _res, next) => next(new ErrorHttp(404, 'ruta_inexistente', 'Esa ruta no existe')));

  // Manejador de errores: un solo formato para todo lo que sale mal.
  app.use((err, req, res, _next) => {
    if (err.type === 'entity.parse.failed') err = new ErrorHttp(400, 'json_invalido', 'El cuerpo no es JSON válido');
    if (err.type === 'entity.too.large') err = new ErrorHttp(413, 'cuerpo_grande', 'El cuerpo supera los 10 KB');
    if (!(err instanceof ErrorHttp)) {
      log('error', { id: req.id, mensaje: err.message, pila: err.stack?.split('\n').slice(0, 3) });
      err = new ErrorHttp(500, 'error_interno', 'Algo salió mal de nuestro lado');
    }
    res.status(err.estado).json({ error: { codigo: err.codigo, mensaje: err.message, detalles: err.detalles }, id: req.id });
  });

  return app;
}

import pg from 'pg';

// La URL de conexión viene del entorno, nunca del código (día 19 de esta parte).
export const pool = new pg.Pool({
  connectionString: process.env.DATABASE_URL,
  max: 10,
});

// src/servidor.js
import { crearApp } from './app.js';
import { log } from './app.js';

const puerto = Number(process.env.PORT ?? 3000);
crearApp().listen(puerto, '127.0.0.1', () => log('info', { evento: 'escuchando', puerto }));

import { test, before, after } from 'node:test';
import assert from 'node:assert/strict';
import { crearApp } from '../src/app.js';
import { pool } from '../src/db.js';

let servidor, base;
const api = async (metodo, ruta, cuerpo, token) => {
  const r = await fetch(base + ruta, {
    method: metodo,
    headers: { 'Content-Type': 'application/json', ...(token && { Authorization: `Bearer ${token}` }) },
    body: cuerpo === undefined ? undefined : JSON.stringify(cuerpo),
  });
  return { estado: r.status, cuerpo: r.status === 204 ? null : await r.json() };
};
const alta = async (email) => {
  await api('POST', '/registro', { email, nombre: 'Prueba', password: 'clave-de-practica-1' });
  return (await api('POST', '/login', { email, password: 'clave-de-practica-1' })).cuerpo.token;
};

before(async () => {
  await pool.query('truncate usuarios, sesiones, envios restart identity cascade');
  servidor = crearApp().listen(0, '127.0.0.1');
  await new Promise((ok) => servidor.once('listening', ok));
  base = `http://127.0.0.1:${servidor.address().port}`;
});
after(async () => { servidor.close(); await pool.end(); });

test('registro: guarda un hash, no la contraseña, y rechaza emails repetidos', async () => {
  const r = await api('POST', '/registro', { email: 'ana@ejemplo.com', nombre: 'Ana', password: 'una-clave-larga-de-practica' });
  assert.equal(r.estado, 201);
  const { rows } = await pool.query("select password_hash from usuarios where email = 'ana@ejemplo.com'");
  assert.match(rows[0].password_hash, /^scrypt\$131072\$8\$1\$/);
  assert.ok(!rows[0].password_hash.includes('una-clave'));
  const otra = await api('POST', '/registro', { email: 'ANA@ejemplo.com', nombre: 'Otra', password: 'otra-clave-larga-1' });
  assert.equal(otra.estado, 409);
});

test('validación: datos inválidos dan 400 con el campo y el problema', async () => {
  const r = await api('POST', '/registro', { email: 'no-es-un-email', nombre: '', password: 'corta' });
  assert.equal(r.estado, 400);
  assert.equal(r.cuerpo.error.codigo, 'entrada_invalida');
  assert.deepEqual(r.cuerpo.error.detalles.map((d) => d.campo).sort(), ['email', 'nombre', 'password']);
});

test('login: contraseña mala y email inexistente dan el mismo 401', async () => {
  const mala = await api('POST', '/login', { email: 'ana@ejemplo.com', password: 'incorrecta-1234' });
  const nadie = await api('POST', '/login', { email: 'nadie@ejemplo.com', password: 'incorrecta-1234' });
  assert.equal(mala.estado, 401);
  assert.equal(nadie.estado, 401);
  assert.deepEqual(mala.cuerpo.error, nadie.cuerpo.error);
});

test('rutas protegidas: sin token o con token inventado, 401', async () => {
  assert.equal((await api('GET', '/envios')).estado, 401);
  assert.equal((await api('GET', '/envios', undefined, 'x'.repeat(43))).estado, 401);
});

test('inyección SQL en el email no logra nada', async () => {
  const r = await api('POST', '/login', { email: "x@y.com' OR '1'='1", password: 'cualquiera-123' });
  assert.equal(r.estado, 400);
});

test('envíos: cada persona ve solo los suyos y un envío ajeno es un 404', async () => {
  const ana = await alta('ana2@ejemplo.com');
  const beto = await alta('beto@ejemplo.com');
  const creado = await api('POST', '/envios', { destinatario: 'Ferretería Norte', direccion: 'Av. Inventada 123', bultos: 12 }, ana);
  assert.equal(creado.estado, 201);
  const id = creado.cuerpo.id;
  assert.equal((await api('GET', `/envios/${id}`, undefined, ana)).estado, 200);
  assert.equal((await api('GET', `/envios/${id}`, undefined, beto)).estado, 404);
  assert.equal((await api('PATCH', `/envios/${id}/estado`, { estado: 'cancelado' }, beto)).estado, 404);
  assert.deepEqual((await api('GET', '/envios', undefined, beto)).cuerpo, []);
  assert.equal((await api('GET', '/envios', undefined, ana)).cuerpo.length, 1);
});

test('regla de negocio: un envío entregado no se puede cancelar', async () => {
  const t = await alta('carla@ejemplo.com');
  const { cuerpo: e } = await api('POST', '/envios', { destinatario: 'Kiosco Sur', direccion: 'Calle Falsa 456', bultos: 3 }, t);
  assert.equal((await api('PATCH', `/envios/${e.id}/estado`, { estado: 'entregado' }, t)).estado, 409);
  assert.equal((await api('PATCH', `/envios/${e.id}/estado`, { estado: 'en_ruta' }, t)).estado, 200);
  assert.equal((await api('PATCH', `/envios/${e.id}/estado`, { estado: 'entregado' }, t)).estado, 200);
  const r = await api('PATCH', `/envios/${e.id}/estado`, { estado: 'cancelado' }, t);
  assert.equal(r.estado, 409);
  assert.equal(r.cuerpo.error.codigo, 'transicion_invalida');
});

test('logout: el token deja de servir', async () => {
  const t = await alta('dani@ejemplo.com');
  assert.equal((await api('GET', '/yo', undefined, t)).estado, 200);
  assert.equal((await api('POST', '/logout', undefined, t)).estado, 204);
  assert.equal((await api('GET', '/yo', undefined, t)).estado, 401);
});

test('errores: JSON roto da 400 y un cuerpo enorme da 413', async () => {
  const roto = await fetch(base + '/login', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: '{"email":' });
  assert.equal(roto.status, 400);
  const grande = await api('POST', '/login', { email: 'a@b.com', password: 'x'.repeat(20000) });
  assert.equal(grande.estado, 413);
});
